head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.param2 = "";
scwin.flag = "0";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 기관명 입력란에 포커스를 주고, 부모화면에서 전달받은 param1이 있으면 즉시 기관정보내역을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.flag = "0";
        ibx_instNm.focus();

        const param = $c.data.getParameter();

        scwin.param1 = $p.parent().scwin.param1;
        scwin.param2 = $p.parent().scwin.param2;

        console.log("scwin.param1 : "+ scwin.param1);

        dlt_list.setCellData(0, "bndInstCd", "00123");
        dlt_list.setCellData(0, "instNm", "테스트");

        if(scwin.param1 !== "") { // undefined 확인필요
            scwin.ins_search("", scwin.param1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90100.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description [조회] 버튼 클릭 — 입력한 기관명(코드) 기준으로 기관정보내역을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_search_onclick(e);
 */
scwin.btn_search_onclick = function (e) {
    try {
        scwin.flag = "1";
        scwin.ins_search(ibx_instNm.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90100.btn_search_onclick" });
    }
};

/**
 * @method
 * @name grd_main_oncelldblclick
 * @description 기관정보내역 그리드 행 더블클릭 — 기관상태가 정상(1)인 기관만 선택 가능하며, 선택한 기관코드·기관명을 부모화면 항목에 설정하고 팝업을 닫는다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_main_oncelldblclick(0, 0, "bndInstCd");
 */
scwin.grd_main_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if(dlt_list.getCellData(rowIndex, "stdCdInstStatCd") !== "1") {
            $c.win.alert("기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.");
            return;
        }

        const bndInstcd = dlt_list.getCellData(rowIndex, "bndInstCd");
        const instNm = dlt_list.getCellData(rowIndex, "instNm");

        $c.cm.ins_popupRtn_cdnm(bndInstcd, instNm);
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90100.grd_main_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description [닫기] 버튼 클릭 — 팝업화면을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_close_onclick(e);
 */
scwin.btn_close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90100.btn_close_onclick" });
    }
};

/**
 * @method
 * @name ibx_instNm_onkeyup
 * @description 기관명 입력란 keyup — 입력값에서 특수문자를 제거한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_instNm_onkeyup(e);
 */
scwin.ibx_instNm_onkeyup = function (e) {
    try {
        scwin.flag = "1";
        $c.cm.fn_DelChar(ibx_instNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90100.ibx_instNm_onkeyup" });
    }
};

/**
 * @method
 * @name ibx_instNm_oneditenter
 * @description 기관명 입력란 Enter 입력 — 입력값이 있으면 기관정보내역을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_instNm_oneditenter(e);
 */
scwin.ibx_instNm_oneditenter = function (e) {
    try {
        scwin.flag = "1";
        if(ibx_instNm.getValue() !== "") {
            scwin.ins_search(ibx_instNm.getValue());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90100.ibx_instNm_oneditenter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sbm_search_submitdone
 * @description 기관정보내역 조회 완료 콜백 — 조회 건수를 총건수 영역에 표시한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_search_submitdone(e);
 */
scwin.sbm_search_submitdone = function (e) {
    spa_totCnt.setValue(dlt_list.getRowCount());
};

/**
 * @method
 * @name ins_search
 * @description 기관명(코드) 조회조건으로 기관정보내역을 조회한다. (조회 : TBLD_B_INST 채권기관 — BND_INST_CD 값이 있는 경우 별도 where절 추가, TBLD_B_CNTR_INFO 국가정보)
 * @param {String} instNm 기관명(코드) 검색어
 * @param {String} mktID 부모화면에서 전달받은 시장 파라미터(param1)
 * @returns {void}
 * @hidden N
 * @example scwin.ins_search(ibx_instNm.getValue());
 */
scwin.ins_search = async function (instNm,mktID) {
    dma_search.set("instNm", instNm);
    dma_search.set("flag", scwin.flag);
    dma_search.set("param1", mktID);
    /*
    dlt_list.insertRow(0);
    dlt_list.setCellData(0, "bndInstCd", "00123");
    dlt_list.setCellData(0, "instNm", "테스트");
    // dlt_list.setCellData(0, "stdCdInstStatCd", "1");
    // grd_main.refreshRow(0);
    */

    const sbmOptions = {
        id : "sbm_search",
        action : "/common/api/bond/bondInst-select",
        method : "get",
        ref : "dma_search",
        target : "dlt_list=body",
        gridview : "grd_main",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.sbm_search_submitdone(sbmRtn);
}
